<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);require_once dirname(__DIR__).'/src/Database.php';require_once dirname(__DIR__).'/src/CommerceStripeService.php';
try{$db=Database::connect(dirname(__DIR__));if(getenv('COMMERCE_PAYMENT_WORKER_ENABLED')!=='1')throw new RuntimeException('Commerce payment worker is disabled.');$q=$db->prepare('SELECT id FROM commerce_organizations WHERE organization_key=?');$q->execute([CommerceAccess::primaryKey()]);$org=(int)$q->fetchColumn();$count=0;$events=$db->prepare("SELECT event_id FROM commerce_provider_webhooks WHERE organization_id=? AND status='queued' AND available_at_utc<=UTC_TIMESTAMP() ORDER BY received_at_utc LIMIT 50");$events->execute([$org]);foreach($events->fetchAll(PDO::FETCH_COLUMN) as $id){CommerceStripeService::processEvent($db,$org,$id);++$count;}$q=$db->prepare("SELECT a.order_id FROM commerce_payment_attempts a JOIN commerce_orders o ON o.id=a.order_id AND o.organization_id=a.organization_id WHERE a.organization_id=? AND a.provider='stripe_test' AND COALESCE(a.last_error_code,'')<>'creation_retry_window_expired' AND o.state IN ('payment_pending','exception','refund_pending') ORDER BY COALESCE(a.last_checked_at_utc,a.provider_created_at_utc) LIMIT 25");$q->execute([$org]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $id){$r=$db->prepare("SELECT 1 FROM commerce_provider_refunds WHERE organization_id=? AND order_id=? AND status='pending'");$r->execute([$org,$id]);if($r->fetchColumn())CommerceStripeService::sendRefund($db,$org,(int)$id);else CommerceStripeService::reconcile($db,$org,(int)$id);++$count;}echo json_encode(['processed'=>$count,'provider'=>'stripe_test']).PHP_EOL;}
catch(Throwable){fwrite(STDERR,"Commerce payment worker unavailable or disabled. Inspect configuration and stored error codes; no sensitive provider responses are logged.\n");exit(1);}
